    </div>
  );
};

/* 稀有度颜色映射 */
const rarityColor: Record<string, string> = {
  common: '#ffffff',
  uncommon: '#1eff00',
  rare: '#0070ff',
  epic: '#a335ee',
  legendary: '#ff8000',
};

const styles: Record<string, React.CSSProperties> = {
  hud: {
    position: 'relative',
